  const selectPromotion=(p:any)=>{setPromotionId(p.id);setSelected(p.service_ids);setStaffId(null);setDate('');setTime('');setAppliedCoupon('');setCouponInput('');setCouponMsg('');setPackCode('');setRewardCode('');setRepeatDays(0);setErr('')};
  useEffect(()=>{if(serviceRequest){if(serviceRequest.promotion){const p=promotions.find((p:any)=>p.id===serviceRequest.id);if(p)selectPromotion(p)}else{setPromotionId(null);setSelected([serviceRequest.id]);setStaffId(null);setDate('');setTime('')}}},[serviceRequest?.key]);
  const chosen=services.filter((svc:any)=>selected.includes(svc.id));const staff=data.staff||[];const compatibleStaff=staff.filter((p:any)=>!p.service_ids?.length||selected.every(id=>p.service_ids.includes(id)));const chosenStaff=staff.find((p:any)=>Number(p.id)===Number(staffId));
  const fallbackDuration=chosen.reduce((a:number,svc:any)=>a+svc.duration_min,0)*partySize,fallbackSubtotal=chosen.reduce((a:number,svc:any)=>a+svc.price_cents,0)*partySize;
  const duration=quote?.duration_min??fallbackDuration,total=quote?.total_cents??(selectedPromotion?selectedPromotion.price_after_cents*partySize:fallbackSubtotal);
  const q=new URLSearchParams(location.search),returnedBooking=q.get('booking'),clientAccess=q.get('clientAccess')||'',[returned,setReturned]=useState<any>(),[paymentMethod,setPaymentMethod]=useState((JSON.parse(b.payment_methods_json||'["mercadopago"]'))[0]||'');
  useEffect(()=>{if(clientAccess)api(`/public/${b.slug}/client-access?token=${encodeURIComponent(clientAccess)}`).then((x:any)=>setClient({name:x.name,email:x.email,phone:x.phone})).catch(e=>setErr(e.message))},[b.slug,clientAccess]);
  useEffect(()=>{if(returnedBooking)api(`/public/${b.slug}/bookings/${returnedBooking}/status?token=${encodeURIComponent(q.get('token')||'')}`).then(setReturned).catch(()=>{})},[returnedBooking]);
