function BookingStep({n,title,text,children}:any){return <div className="bookingStep"><div className="stepTitle"><span>{n}</span><div><h3>{title}</h3><p>{text}</p></div></div>{children}</div>}

// ---------------- SUPER ADMIN ----------------
function SuperAdmin(){
  const[tab,setTab]=useState(new URLSearchParams(location.search).get('tab')||'Resumen');
  const select=(section:string)=>{setTab(section);history.replaceState({},'',`/super-admin?tab=${encodeURIComponent(section)}`)};
  const tabs=[['Resumen',BarChart3],['Negocios',Users],['Planes',CreditCard],['Suscripciones',WalletCards],['Soporte',CircleHelp],['FAQ de la Home',CircleHelp],['Textos legales',FileText],['Configuración',Settings],['Cambiar contraseña',LockKeyhole]] as const;
  return <PanelLayout variant="superLayout" brand={<Logo light/>} identity={<span className="superTag"><ShieldCheck size={15}/> SUPER ADMIN</span>} title="Menú de superadministración" items={tabs} active={tab} onSelect={select} onLogout={async()=>{await api('/auth/logout',{method:'POST'});navigate('/')}}>
    {tab==='Resumen'?<SuperOverview/>:tab==='Negocios'?<SuperBusinesses/>:tab==='Planes'?<SuperPlans/>:tab==='Suscripciones'?<PlatformSubscriptions/>:tab==='Soporte'?<SupportInbox/>:tab==='FAQ de la Home'?<HomeFaqAdmin/>:tab==='Textos legales'?<LegalAdmin/>:tab==='Cambiar contraseña'?<PasswordSettings role="superadmin"/>:<SuperSettings/>}
  </PanelLayout>;
}
function SuperOverview(){const[d,setD]=useState<any>();useEffect(()=>{api('/admin/overview').then(setD).catch(()=>navigate('/login'))},[]);if(!d)return <PanelLoading/>;return <><h1>Adara Web</h1><p className="lead">Este panel administra cuentas y suscripciones. Las reservas y clientes de cada negocio permanecen dentro de su propio espacio.</p><div className="stats superStats"><Stat icon={Users} label="Cuentas" value={d.users}/><Stat icon={Globe} label="Negocios activos" value={d.active}/><Stat icon={Clock3} label="En prueba" value={d.trialing}/><Stat icon={CheckCircle2} label="Suscripciones activas" value={d.paid}/><Stat icon={CreditCard} label="MRR estimado" value={money(d.mrr_cents)}/></div><div className="panel"><h2>Altas recientes</h2>{d.stores.map((x:any)=><div className="row" key={x.id}><div><b>{x.name}</b><small>{x.owner_email}</small></div><span>{x.plan_name} · {x.billing_cycle==='annual'?'Anual':'Mensual'} · {x.email_verified?'Email verificado':'Sin verificar'}</span><StatusBadge status={x.status}/></div>)}</div></>}
function SuperBusinesses(){const[list,setList]=useState<any[]>([]),[plans,setPlans]=useState<any[]>([]),[msg,setMsg]=useState('');const load=()=>Promise.all([api('/admin/businesses'),api('/admin/plans')]).then(([a,p])=>{setList(a);setPlans(p)});useEffect(()=>{load().catch(()=>navigate('/login'))},[]);const update=async(x:any,patch:any)=>{await api('/admin/businesses/'+x.id,{method:'PATCH',body:JSON.stringify(patch)});setMsg(`Cambios guardados para ${x.name}`);load()};const verify=async(x:any)=>{await api('/admin/users/'+x.owner_id,{method:'PATCH',body:JSON.stringify({email_verified:true})});load()};return <><h1>Negocios y suscripciones</h1><p className="lead">Acá manejás la cuenta, el plan y el precio que paga cada negocio. No se muestran las reservas ni los clientes de los profesionales. Los contratos con renovación se gestionan desde Suscripciones.</p>{msg&&<div className="successBox"><CheckCircle2/>{msg}</div>}<div className="businessTable">{list.map(x=>{const normalMonthly=x.monthly_price_cents/100,normalAnnual=x.annual_price_cents/100;return <article key={x.id}><div className="businessMain"><div className="avatar">{x.name[0]}</div><div><h3>{x.name}</h3><span>{x.owner_name} · {x.owner_email}</span><small>{x.email_verified?'Email verificado':'Email pendiente'} · Alta: {new Date(x.created_at).toLocaleDateString('es-AR')}</small><small>Prueba hasta: {x.trial_ends_at?new Date(x.trial_ends_at).toLocaleDateString('es-AR'):'—'}</small>{!x.email_verified&&<button className="miniAction" onClick={()=>verify(x)}>Marcar email como verificado</button>}</div></div><div className="adminControls accountControls"><label>Plan<select disabled={!!x.recurring_active} value={x.plan_slug} onChange={e=>update(x,{plan_slug:e.target.value})}>{plans.filter(p=>p.active||p.slug===x.plan_slug).map(p=><option value={p.slug} key={p.slug}>{p.name}{!p.public_enabled?' · oculto':''}</option>)}</select></label><label>Facturación<select disabled={!!x.recurring_active} value={x.billing_cycle} onChange={e=>update(x,{billing_cycle:e.target.value})}><option value="monthly">Mensual</option><option value="annual">Anual</option></select></label><label>Suscripción<select disabled={!!x.recurring_active} value={x.subscription_status} onChange={e=>update(x,{subscription_status:e.target.value})}><option value="trialing">Prueba</option><option value="active">Activa</option><option value="past_due">Pago pendiente</option><option value="cancelled">Cancelada</option></select></label><label>Fin de prueba<input disabled={!!x.recurring_active} type="date" value={x.trial_ends_at?String(x.trial_ends_at).slice(0,10):''} onChange={e=>update(x,{trial_ends_at:e.target.value?new Date(e.target.value+'T23:59:59').toISOString():null})}/></label><div className="customPriceBox"><b>Precio especial para esta cuenta</b><small>Dejalo vacío para usar el precio público del plan. Un contrato existente conserva su importe hasta cancelar y volver a autorizar.</small><label>Mensual $<input type="number" min="0" defaultValue={x.custom_monthly_price_cents!=null?x.custom_monthly_price_cents/100:''} placeholder={String(normalMonthly)} onBlur={e=>update(x,{custom_monthly_price:e.target.value===''?null:Number(e.target.value)})}/></label><label>Anual $<input type="number" min="0" defaultValue={x.custom_annual_price_cents!=null?x.custom_annual_price_cents/100:''} placeholder={String(normalAnnual)} onBlur={e=>update(x,{custom_annual_price:e.target.value===''?null:Number(e.target.value)})}/></label></div><label className="adminNotes">Notas internas<textarea defaultValue={x.admin_notes||''} placeholder="Ej: precio especial por conocida, acuerdo comercial..." onBlur={e=>update(x,{admin_notes:e.target.value})}/></label><button className={x.status==='active'?'dangerButton':'dark'} onClick={()=>update(x,{status:x.status==='active'?'suspended':'active'})}>{x.status==='active'?<><Ban size={15}/>Suspender</>:<><CheckCircle2 size={15}/>Reactivar</>}</button></div></article>})}</div></>}

function SuperPlans(){
  const[list,setList]=useState<any[]>([]),[showNew,setShowNew]=useState(false);const load=()=>api('/admin/plans').then(setList);useEffect(()=>{load()},[]);
  return <><span className="kicker">MONETIZACIÓN</span><h1>Planes y precios</h1><p className="lead">Hoy podés dejar un solo plan visible. Cuando quieras sumar otro, lo creás acá y decidís cuándo publicarlo en el Home y el registro.</p><div className="panelTitle"><div><b>{list.filter(x=>x.active&&x.public_enabled).length} plan público activo</b><small>Los planes ocultos siguen disponibles para administrar cuentas existentes.</small></div><button className="dark" onClick={()=>setShowNew(v=>!v)}><Plus size={16}/>{showNew?'Cerrar':'Crear nuevo plan'}</button></div>{showNew&&<NewPlanForm onSaved={()=>{setShowNew(false);load()}}/>}<div className="superPlanGrid">{list.map(p=><PlanEditor key={p.slug} plan={p} onSaved={load}/>)}</div></>
}
function NewPlanForm({onSaved}:any){
  const[f,setF]=useState<any>({name:'',monthly_price:0,annual_price:0,max_services:100,max_promotions:30,max_posts:100,max_coupons:50,max_staff:1,template_level:3,analytics_enabled:true,public_enabled:false,active:true,features:'Página profesional\nAgenda y reservas\nMercado Pago propio'}),[err,setErr]=useState('');
  return <form className="panel form" onSubmit={async e=>{e.preventDefault();setErr('');try{await api('/admin/plans',{method:'POST',body:JSON.stringify({...f,features:String(f.features).split('\n').map((x:string)=>x.trim()).filter(Boolean)})});onSaved()}catch(e:any){setErr(e.message)}}}>{err&&<div className="error">{err}</div>}<h2>Nuevo plan</h2><div className="two"><label>Nombre<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Descripción<input value={f.description||''} onChange={e=>setF({...f,description:e.target.value})}/></label></div><div className="two"><label>Mensual $<input type="number" min="0" value={f.monthly_price} onChange={e=>setF({...f,monthly_price:e.target.value})}/></label><label>Anual $<input type="number" min="0" value={f.annual_price} onChange={e=>setF({...f,annual_price:e.target.value})}/></label></div><div className="two"><label>Máximo de integrantes<input type="number" min="1" max="50" value={f.max_staff||1} onChange={e=>setF({...f,max_staff:e.target.value})}/><small>1 = profesional independiente; 2 o más = plan de equipo.</small></label></div><label>Beneficios (uno por línea)<textarea value={f.features} onChange={e=>setF({...f,features:e.target.value})}/></label><label className="switchLine"><input type="checkbox" checked={!!f.public_enabled} onChange={e=>setF({...f,public_enabled:e.target.checked})}/> Mostrar públicamente al crearlo</label><button className="dark">Crear plan</button></form>
}
function PlanEditor({plan,onSaved}:any){
  const[f,setF]=useState<any>({...plan,monthly_price:plan.monthly_price_cents/100,annual_price:plan.annual_price_cents/100,features:(plan.features||[]).join('\n')}),[msg,setMsg]=useState(''),[err,setErr]=useState('');
  useEffect(()=>setF({...plan,monthly_price:plan.monthly_price_cents/100,annual_price:plan.annual_price_cents/100,features:(plan.features||[]).join('\n')}),[plan.id,plan.updated_at,plan.public_enabled,plan.active,plan.monthly_price_cents,plan.annual_price_cents]);
  const save=async(e:any)=>{e.preventDefault();setErr('');try{await api('/admin/plans/'+plan.slug,{method:'PUT',body:JSON.stringify({...f,features:String(f.features).split('\n').map((x:string)=>x.trim()).filter(Boolean)})});setMsg('Guardado');onSaved()}catch(e:any){setErr(e.message)}};
  return <form className={'panel form planEditor '+(plan.public_enabled?'publicPlanEditor':'')} onSubmit={save}><div className="planEditorTop"><span className="kicker">{plan.slug.toUpperCase()}</span><span className={'status '+(plan.public_enabled&&plan.active?'active':'cancelled')}>{plan.public_enabled&&plan.active?'Visible':'Oculto'}</span></div>{err&&<div className="error">{err}</div>}<label>Nombre<input value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Descripción<textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><div className="two"><label>Mensual $<input type="number" value={f.monthly_price} onChange={e=>setF({...f,monthly_price:e.target.value})}/></label><label>Anual $<input type="number" value={f.annual_price} onChange={e=>setF({...f,annual_price:e.target.value})}/></label></div><div className="two"><label>Servicios<input type="number" value={f.max_services} onChange={e=>setF({...f,max_services:e.target.value})}/></label><label>Cupones<input type="number" value={f.max_coupons} onChange={e=>setF({...f,max_coupons:e.target.value})}/></label><label>Promociones<input type="number" value={f.max_promotions} onChange={e=>setF({...f,max_promotions:e.target.value})}/></label><label>Novedades<input type="number" value={f.max_posts} onChange={e=>setF({...f,max_posts:e.target.value})}/></label><label>Integrantes / agendas<input type="number" min="1" max="50" value={f.max_staff||1} onChange={e=>setF({...f,max_staff:e.target.value})}/></label></div><label>Nivel de plantillas<select value={f.template_level} onChange={e=>setF({...f,template_level:e.target.value})}><option value="1">Esenciales</option><option value="2">Estándar</option><option value="3">Todas + premium</option></select></label><label>Beneficios (uno por línea)<textarea value={f.features} onChange={e=>setF({...f,features:e.target.value})}/></label><div className="planToggles"><label className="switchLine"><input type="checkbox" checked={!!f.active} onChange={e=>setF({...f,active:e.target.checked})}/> Plan activo</label><label className="switchLine"><input type="checkbox" checked={!!f.public_enabled} onChange={e=>setF({...f,public_enabled:e.target.checked})}/> Mostrar en Home y registro</label><label className="switchLine"><input type="checkbox" checked={!!f.analytics_enabled} onChange={e=>setF({...f,analytics_enabled:e.target.checked})}/> Estadísticas</label><label className="switchLine"><input type="checkbox" checked={!!f.highlighted} onChange={e=>setF({...f,highlighted:e.target.checked})}/> Destacar</label></div>{msg&&<small className="success">{msg}</small>}<div className="planActions"><button className="dark">Guardar plan</button><button type="button" className="dangerLink" onClick={async()=>{if(!confirm('¿Eliminar este plan? Solo se puede si ninguna cuenta lo usa.'))return;try{await api('/admin/plans/'+plan.slug,{method:'DELETE'});onSaved()}catch(e:any){setErr(e.message)}}}>Eliminar</button></div></form>
}

function SuperSettings(){const[d,setD]=useState<any>(),[days,setDays]=useState(15),[grace,setGrace]=useState(3),[settingsError,setSettingsError]=useState(''),[saving,setSaving]=useState(false),[msg,setMsg]=useState('');useEffect(()=>{api('/admin/settings').then((x:any)=>{setD(x);setDays(x.trial_days);setGrace(x.billing?.grace_days??3)})},[]);if(!d)return <PanelLoading/>;return <><span className="kicker">PLATAFORMA</span><h1>Configuración general</h1><div className="panel form"><label>Días de prueba gratis<select value={days} onChange={e=>setDays(Number(e.target.value))}><option value="7">7 días (una semana)</option><option value="15">15 días</option></select></label><label>Días de gracia para renovaciones pendientes<input aria-label="Días de gracia para renovaciones pendientes" type="number" min="0" max="14" value={grace} onChange={e=>setGrace(Number(e.target.value))}/><small>Se aplican después de un período pagado, cuando la renovación sigue activa. La prueba gratuita conserva su vencimiento.</small></label><fieldset className="homeContactSettings"><legend>WhatsApp del home de Adara</legend><label className="switchLine"><input type="checkbox" checked={!!d.home_whatsapp_enabled} onChange={e=>setD({...d,home_whatsapp_enabled:e.target.checked})}/> Mostrar botón de WhatsApp en el home</label><label>Número de WhatsApp de soporte<input type="tel" inputMode="tel" aria-label="Número de WhatsApp de soporte" value={d.home_whatsapp_phone||''} onChange={e=>setD({...d,home_whatsapp_phone:e.target.value})}/><small>Incluí el código de país. Para un celular argentino: 54 + 9 + código de área + número, sin 0 ni 15.</small></label><label>Mensaje inicial de soporte<textarea aria-label="Mensaje inicial de soporte" maxLength={500} value={d.home_whatsapp_message||''} onChange={e=>setD({...d,home_whatsapp_message:e.target.value})}/></label><small>Abre tu chat de soporte. Es independiente de los recordatorios automáticos de WhatsApp Business.</small></fieldset><fieldset className="homeAnalyticsSettings"><legend>Google Analytics del Home de Adara</legend><label>ID de medición del Home<input aria-label="ID de Google Analytics del Home" placeholder="G-XXXXXXXXXX" maxLength={32} value={d.home_ga_id||''} onChange={e=>setD({...d,home_ga_id:e.target.value})}/></label><label className="switchLine"><input type="checkbox" checked={!!d.home_analytics_enabled} onChange={e=>setD({...d,home_analytics_enabled:e.target.checked})}/> Activar Google Analytics del Home</label><small>Se activa cuando el visitante acepta la medición. Envía visitas al Home y al registro, clics para crear una cuenta y cuentas creadas antes de verificar el email. Los informes se consultan en Google Analytics. Las páginas de los profesionales usan sus propios IDs.</small></fieldset><fieldset className="homeAnalyticsSettings"><legend>Meta Pixel del Home de Adara</legend><label>ID de Meta Pixel del Home<input aria-label="ID de Meta Pixel del Home" inputMode="numeric" placeholder="Ej.: 123456789012345" maxLength={25} value={d.home_meta_pixel_id||''} onChange={e=>setD({...d,home_meta_pixel_id:e.target.value})}/></label><label className="switchLine"><input type="checkbox" checked={!!d.home_meta_enabled} onChange={e=>setD({...d,home_meta_enabled:e.target.checked})}/> Activar Meta Pixel del Home</label><small>Se carga sólo si el visitante acepta Publicidad (Meta Pixel). Mide PageView, el evento personalizado RegistrationStart y CompleteRegistration al crear una cuenta, antes de verificar el email. No mide pagos ni envía datos de los formularios. Pegá sólo el ID numérico: no se necesita access token ni client secret. Los eventos se revisan en el Administrador de eventos de Meta. Guardar no confirma que Meta los haya recibido.</small></fieldset><fieldset className="homeSocialSettings"><legend>Redes de Adara Web</legend><p>Se muestran en el pie del Home. Dejá un campo vacío para ocultarlo.</p>{[['instagram','Instagram'],['facebook','Facebook'],['tiktok','TikTok'],['youtube','YouTube'],['linkedin','LinkedIn']].map(([key,label])=><label key={key}>{label}<input type="url" maxLength={500} placeholder="https://..." value={d.home_socials?.[key]||''} onChange={e=>setD({...d,home_socials:{...d.home_socials,[key]:e.target.value}})}/></label>)}</fieldset><button className="dark" disabled={saving} onClick={async()=>{setSaving(true);setSettingsError('');setMsg('');try{await api('/admin/settings',{method:'PUT',body:JSON.stringify({trial_days:days,billing_grace_days:grace,home_whatsapp_enabled:!!d.home_whatsapp_enabled,home_whatsapp_phone:d.home_whatsapp_phone||'',home_whatsapp_message:d.home_whatsapp_message||'',home_socials:d.home_socials||{},home_ga_id:d.home_ga_id||'',home_analytics_enabled:!!d.home_analytics_enabled,home_meta_pixel_id:d.home_meta_pixel_id||'',home_meta_enabled:!!d.home_meta_enabled})});setMsg('Guardado')}catch(e:any){setSettingsError(e.message)}finally{setSaving(false)}}}>Guardar</button>{settingsError&&<p role="alert" className="errorText">{settingsError}</p>}{msg&&<p className="success">{msg}</p>}</div><div className="integrationGrid"><article><b>Email transaccional</b><span>{d.email_configured?'Configurado':'Modo local'}</span></article><article><b>Mercado Pago OAuth</b><span>{d.mp_oauth_configured?'Configurado':'Faltan credenciales'}</span></article><article><b>Suscripciones de Adara</b><span>{d.billing?.configured?'Configuradas':d.billing?.demo?'Simulación local':'Conexión pendiente'}</span></article><article><b>Pagos de prueba</b><span>{d.demo_payments?'Habilitados':'Deshabilitados'}</span></article></div></>}
